// HasLot applies the HasEdge predicate on the "lot" edge.
func HasLot() predicate.Bobbin {
	return predicate.Bobbin(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, LotTable, LotColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasLotWith applies the HasEdge predicate on the "lot" edge with a given conditions (other predicates).
func HasLotWith(preds ...predicate.Lot) predicate.Bobbin {
	return predicate.Bobbin(func(s *sql.Selector) {
		step := newLotStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Bobbin) predicate.Bobbin {
	return predicate.Bobbin(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Bobbin) predicate.Bobbin {
	return predicate.Bobbin(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Bobbin) predicate.Bobbin {
	return predicate.Bobbin(sql.NotPredicates(p))
}
